package ktanesolver.module.modded.regular.discoloredsquares;
import static org.assertj.core.api.Assertions.assertThat;import java.util.List;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class DiscoloredSquaresSolverTest{@Test void remembersInitialOrderAndSolvesStageOne(){var s=new DiscoloredSquaresSolver();var m=new ModuleEntity();var initial=List.of("Blue","Green","Green","Green","Green","Red","Green","Green","Green","Green","Yellow","Green","Green","Green","Green","Magenta");var first=(SolveSuccess<DiscoloredSquaresOutput>)s.solve(new RoundEntity(),new BombEntity(),m,new DiscoloredSquaresInput(0,initial));assertThat(first.solved()).isFalse();assertThat(first.output().presses()).containsExactly("A1","B2","C3","D4");var stage=List.of("Blue","Red","Yellow","Green","Magenta","Blue","Red","Yellow","Green","Magenta","Blue","Red","Yellow","Green","Magenta","Red");var next=(SolveSuccess<DiscoloredSquaresOutput>)s.solve(new RoundEntity(),new BombEntity(),m,new DiscoloredSquaresInput(1,stage));assertThat(next.solved()).isFalse();assertThat(next.output().presses()).isNotEmpty();assertThat(m.getState()).containsKey("discoloredRemembered");}}
